static FOLDER_CLOSED: &str = I_FOLDER;
static FOLDER_OPEN: &str = I_FOLDER_OPEN;
static FILE: &str = I_FILE;

/// Which icon an entry gets.
///
/// Returns the icon's complete `<svg>` markup, ready for
/// `dangerous_inner_html`. The whole element is kept rather than
/// flattened to `<path>`s because 184 icons rely on `<g>`, `<circle>`,
/// `<rect>`, gradients or `<use>`, and on theme brand colours that are
/// deliberately not overridden.
///
/// Order: exact file name (so `README.md` beats the `md` rule) →
/// extension → directory → generic `file`. Directories prefer their
/// paired `folder-<name>-open` variant while expanded.
///
/// Lookups allocate nothing: `eq_ignore_ascii_case` over static tables,
/// because `ext` is already lowercased when the directory is read.
pub fn icon_for(
    name: &str,
    ext: &str,
    is_dir: bool,
    expanded: bool,
) -> &'static str {
    if is_dir {
        for (dir, closed, opened) in DIR_ICONS {
            if dir.eq_ignore_ascii_case(name) {
                return if expanded && opened.is_some() {
                    opened.unwrap()
                } else {
                    closed
                };
            }
        }
        return if expanded { FOLDER_OPEN } else { FOLDER_CLOSED };
    }

    for (file_name, icon) in NAME_ICONS {
        if file_name.eq_ignore_ascii_case(name) {
            return icon;
        }
    }

    for (extension, icon) in EXT_ICONS {
        if *extension == ext {
            return icon;
        }
    }

    FILE
}
